mapper.select:
SELECT 
FROM workflow_action_log log

WHERE log.tenant_id = #{tenantId}
  AND log.instance_id = #{instanceId}
ORDER BY log.created_at, log.id

SELECT 
FROM workflow_action_log log
JOIN workflow_instance instance
  ON instance.id = log.instance_id
 AND instance.tenant_id = log.tenant_id

WHERE log.tenant_id = #{tenantId}
  AND instance.business_type = #{businessType}
  AND instance.business_id = #{businessId}
ORDER BY log.created_at, log.id

SELECT COUNT(*)
FROM workflow_action_log
WHERE tenant_id = #{tenantId}
  AND instance_id = #{instanceId}
  AND target_user_id = #{targetUserId}
  AND action = #{action}
